argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
Add-Type -AssemblyName System.Windows.Forms
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'No visible Edge window'}
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$editName=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('5paH5a2X5qyE5L2N56m655m944CC6KuL6Ly45YWl5YWn5a655Lul5pKw5a+r5paw6LK85paH44CC'))
$attachName=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('6ZmE5Yqg5b2x6Z+z5YWn5a65'))
$edit=$null;$attach=$null
for($i=0;$i -lt $all.Count;$i++){
  $e=$all.Item($i)
  if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit -and [string]$e.Current.Name -eq $editName){$edit=$e}
  if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and [string]$e.Current.Name -eq $attachName){$attach=$e}
}
if($null -eq $edit){throw 'Threads composer edit not found'}
if($null -eq $attach){throw 'Threads attach button not found'}
$edit.SetFocus()
$txt=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
Set-Clipboard -Value $txt
Start-Sleep -Milliseconds 200
[System.Windows.Forms.SendKeys]::SendWait('^a')
[System.Windows.Forms.SendKeys]::SendWait('^v')
Start-Sleep -Milliseconds 400
$inv=$attach.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
$inv.Invoke()
Start-Sleep -Seconds 2
$desk=[System.Windows.Automation.AutomationElement]::RootElement
$all2=$desk.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$fileEdit=$null
for($i=0;$i -lt $all2.Count;$i++){
  $e=$all2.Item($i)
  if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit -and [string]$e.Current.AutomationId -eq '1148'){$fileEdit=$e;break}
}
if($null -eq $fileEdit){
  for($i=0;$i -lt $all2.Count;$i++){
    $e=$all2.Item($i)
    if($e.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit){
      $r=$e.Current.BoundingRectangle
      if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 500){$fileEdit=$e;break}
    }
  }
}
if($null -eq $fileEdit){throw 'File picker filename field not found'}
try{
  $vp=$fileEdit.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern)
  $vp.SetValue('C:\Users\alston.huang\Downloads\Gemini_Generated_Image_iltypdiltypdilty.jpg')
}catch{
  $fileEdit.SetFocus()
  Set-Clipboard -Value 'C:\Users\alston.huang\Downloads\Gemini_Generated_Image_iltypdiltypdilty.jpg'
  [System.Windows.Forms.SendKeys]::SendWait('^a')
  [System.Windows.Forms.SendKeys]::SendWait('^v')
}
Start-Sleep -Milliseconds 300
$fileEdit.SetFocus()
[System.Windows.Forms.SendKeys]::SendWait('{ENTER}')
Start-Sleep -Seconds 6
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$out=@()
for($i=0;$i -lt $all.Count;$i++){
 $e=$all.Item($i)
 $ct=$e.Current.ControlType.ProgrammaticName
 $name=[string]$e.Current.Name
 if(($ct -match 'Button|Edit|Text|Image') -and $name){
   $r=$e.Current.BoundingRectangle
   if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 350 -and $r.Y -lt 800){
     $out += [pscustomobject]@{type=$ct;name=$name;aid=[string]$e.Current.AutomationId;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height;enabled=[bool]$e.Current.IsEnabled}
   }
 }
}
[pscustomobject]@{text_chars=$txt.Length;image_path='C:\Users\alston.huang\Downloads\Gemini_Generated_Image_iltypdiltypdilty.jpg';controls=$out}|ConvertTo-Json -Depth 6 -Compress
